<?php
declare(strict_types=1);require __DIR__.'/inc/db.php';require __DIR__.'/inc/env.php';$config=require __DIR__.'/inc/xendit.php';header('Content-Type: application/json');
$callback=(string)env_value('XENDIT_WEBHOOK_TOKEN','');if($callback!==''&&!hash_equals($callback,(string)($_SERVER['HTTP_X_CALLBACK_TOKEN']??''))){http_response_code(401);echo json_encode(['ok'=>false]);exit;}
$data=json_decode((string)file_get_contents('php://input'),true);$invoiceId=trim((string)($data['id']??''));if($invoiceId===''){http_response_code(400);echo json_encode(['ok'=>false]);exit;}
$secret=(string)$config['secret_key'];$ch=curl_init('https://api.xendit.co/v2/invoices/'.rawurlencode($invoiceId));curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_HTTPAUTH=>CURLAUTH_BASIC,CURLOPT_USERPWD=>$secret.':',CURLOPT_TIMEOUT=>20,CURLOPT_SSL_VERIFYPEER=>true]);$raw=curl_exec($ch);$http=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);$invoice=json_decode((string)$raw,true);if($http<200||$http>=300||!is_array($invoice)){http_response_code(202);echo json_encode(['ok'=>false]);exit;}if(($invoice['status']??'')!=='PAID'){echo json_encode(['ok'=>true,'changed'=>false]);exit;}$number=trim((string)($invoice['external_id']??''));
$pdo->beginTransaction();try{$q=$pdo->prepare('SELECT * FROM order_headers WHERE order_number=? FOR UPDATE');$q->execute([$number]);$h=$q->fetch();if(!$h)throw new RuntimeException('Order not found.');if($h['payment_status']==='paid'){$pdo->commit();echo json_encode(['ok'=>true,'changed'=>false]);exit;}$pdo->prepare("UPDATE order_headers SET payment_status='paid',payment_reference=? WHERE id=?")->execute([$invoiceId,$h['id']]);if($h['order_type']==='ai')$pdo->prepare("UPDATE ai_cake_orders SET payment_status='paid',payment_reference=?,payment_invoice_id=? WHERE id=?")->execute([$invoiceId,$invoiceId,$h['ai_order_id']]);else $pdo->prepare("UPDATE orders SET payment_status='paid',payment_reference=?,paid_at=NOW(),payment_invoice_id=? WHERE id=?")->execute([$invoiceId,$invoiceId,$h['normal_order_id']]);$pdo->prepare("INSERT INTO order_status_history(order_header_id,from_status,to_status,note) VALUES(?,?,?,'GCash payment verified by Xendit')")->execute([$h['id'],$h['status'],$h['status']]);$pdo->commit();echo json_encode(['ok'=>true,'changed'=>true]);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log('Xendit webhook: '.$e->getMessage());http_response_code(202);echo json_encode(['ok'=>false]);}
